import { Composio, OpenAIProvider } from "@composio/core";
import { OpenAI } from "openai";
import * as fs from "fs";
import * as path from "path";

async function main() {
  // Read trial_id from /logs/trial_id
  const trialIdPath = "/logs/trial_id";
  const trialId = fs.readFileSync(trialIdPath, "utf-8").trim();
  console.log(`Trial ID: ${trialId}`);

  // Initialize Composio with OpenAIProvider
  const composio = new Composio(new OpenAIProvider());

  // Create a session for zealt-user01
  const session = await composio.createSession("zealt-user01");
  console.log("Session created for zealt-user01");

  try {
    // Fetch the last 5 emails from Gmail
    console.log("Fetching last 5 emails from Gmail...");
    const emailResponse = await session.execute("GMAIL_LIST_MESSAGES", {
      maxResults: 5,
    });

    console.log("Emails fetched:", JSON.stringify(emailResponse, null, 2));

    // Create a summary of email subjects
    let summary = "📧 **Email Summary**\n\n";

    if (emailResponse && emailResponse.data && emailResponse.data.messages) {
      summary += `Found ${emailResponse.data.messages.length} recent emails:\n\n`;

      for (let i = 0; i < emailResponse.data.messages.length; i++) {
        const message = emailResponse.data.messages[i];
        const subject = message.subject || "No subject";
        const from = message.from || "Unknown sender";
        summary += `${i + 1}. **${subject}**\n   From: ${from}\n\n`;
      }
    } else {
      summary += "No emails found or unable to fetch emails.\n";
    }

    console.log("Summary created:", summary);

    // Post the summary to Slack channel
    const channelName = `summary-${trialId}`;
    console.log(`Posting summary to Slack channel: ${channelName}`);

    const slackResponse = await session.execute("SLACK_CHAT_POST_MESSAGE", {
      channel: channelName,
      text: summary,
    });

    console.log("Summary posted to Slack:", JSON.stringify(slackResponse, null, 2));
    console.log("✅ Successfully summarized Gmail emails to Slack!");
  } catch (error) {
    console.error("Error during execution:", error);
    throw error;
  }
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

