import { Composio } from "@composio/core";
import { OpenAIProvider } from "@composio/openai";
import { OpenAI } from "openai";
import * as fs from "fs";

async function main() {
  // Read trial_id from /logs/trial_id
  const trialIdPath = "/logs/trial_id";
  const trialId = fs.readFileSync(trialIdPath, "utf-8").trim();
  console.log(`Trial ID: ${trialId}`);

  // Initialize Composio with OpenAIProvider
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
    provider: new OpenAIProvider(),
  });

  // Get tools for the user
  const userId = "zealt-user01";
  console.log(`Getting tools for user: ${userId}`);

  const tools = await composio.tools.get(userId, {
    toolkits: ["gmail", "slack"],
  });

  console.log("Available tools:", tools.length);

  // Initialize OpenAI
  const openai = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY || "",
  });

  try {
    // Step 1: Fetch the last 5 emails from Gmail
    console.log("Fetching last 5 emails from Gmail...");

    const emailPrompt = `Fetch the last 5 emails from my Gmail account. Return the subject and sender for each email.`;

    const emailResponse = await openai.chat.completions.create({
      model: "gpt-4",
      messages: [{ role: "user", content: emailPrompt }],
      tools,
    });

    console.log("OpenAI response received");

    // Execute tool calls for Gmail
    let emailData: any[] = [];
    if (emailResponse.choices[0].message.tool_calls) {
      for (const toolCall of emailResponse.choices[0].message.tool_calls) {
        console.log(`Executing tool: ${toolCall.function.name}`);
        const result = await composio.tools.execute(toolCall.function.name, {
          userId,
          arguments: JSON.parse(toolCall.function.arguments),
        });
        console.log("Tool result:", JSON.stringify(result, null, 2));

        // Parse the result to extract email information
        if (result && result.data && result.data.messages) {
          emailData = result.data.messages;
        }
      }
    }

    // Step 2: Create a summary of email subjects
    console.log("Creating email summary...");
    let summary = "📧 **Email Summary**\n\n";

    if (emailData && emailData.length > 0) {
      summary += `Found ${emailData.length} recent emails:\n\n`;

      for (let i = 0; i < Math.min(emailData.length, 5); i++) {
        const message = emailData[i];
        const subject = message.subject || "No subject";
        const from = message.from || "Unknown sender";
        summary += `${i + 1}. **${subject}**\n   From: ${from}\n\n`;
      }
    } else {
      summary += "No emails found or unable to fetch emails.\n";
    }

    console.log("Summary created:", summary);

    // Step 3: Post the summary to Slack channel
    const channelName = `summary-${trialId}`;
    console.log(`Posting summary to Slack channel: ${channelName}`);

    const slackPrompt = `Post the following message to the Slack channel "${channelName}":\n\n${summary}`;

    const slackResponse = await openai.chat.completions.create({
      model: "gpt-4",
      messages: [{ role: "user", content: slackPrompt }],
      tools,
    });

    console.log("OpenAI response for Slack received");

    // Execute tool calls for Slack
    if (slackResponse.choices[0].message.tool_calls) {
      for (const toolCall of slackResponse.choices[0].message.tool_calls) {
        console.log(`Executing tool: ${toolCall.function.name}`);
        const result = await composio.tools.execute(toolCall.function.name, {
          userId,
          arguments: JSON.parse(toolCall.function.arguments),
        });
        console.log("Slack tool result:", JSON.stringify(result, null, 2));
      }
    }

    console.log("✅ Successfully summarized Gmail emails to Slack!");
  } catch (error) {
    console.error("Error during execution:", error);
    throw error;
  }
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

