import { Composio } from "@composio/core";

async function main() {
  // Initialize Composio
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
  });

  const userId = "zealt-user01";
  console.log(`User ID: ${userId}`);

  try {
    // Get all available tools for Gmail
    console.log("Fetching Gmail tools...");
    const gmailTools = await composio.tools.get(userId, {
      toolkits: ["gmail"],
      limit: 100,
    });
    console.log(`Found ${gmailTools.length} Gmail tools`);
    console.log("Gmail tool names:");
    for (const tool of gmailTools) {
      console.log(`  - ${tool.function?.name || tool.name}`);
    }

    // Get all available tools for Slack
    console.log("\nFetching Slack tools...");
    const slackTools = await composio.tools.get(userId, {
      toolkits: ["slack"],
      limit: 100,
    });
    console.log(`Found ${slackTools.length} Slack tools`);
    console.log("Slack tool names:");
    for (const tool of slackTools) {
      console.log(`  - ${tool.function?.name || tool.name}`);
    }
  } catch (error) {
    console.error("Error:", error);
  }
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

