import * as fs from "fs";

async function main() {
  // Read trial_id from /logs/trial_id
  const trialIdPath = "/logs/trial_id";
  const trialId = fs.readFileSync(trialIdPath, "utf-8").trim();
  console.log(`Trial ID: ${trialId}`);

  // Initialize Composio
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
  });

  const userId = "zealt-user01";
  console.log(`User ID: ${userId}`);

  try {
    // Step 1: Fetch the last 5 emails from Gmail
    console.log("Fetching last 5 emails from Gmail...");

    const emailResult = await composio.tools.execute("GMAIL_FETCH_EMAILS", {
      userId,
      arguments: {
        maxResults: 5,
      },
    });

    console.log("Emails fetched:", JSON.stringify(emailResult, null, 2));

    // Step 2: Create a summary of email subjects
    console.log("Creating email summary...");
    let summary = "📧 **Email Summary**\n\n";

    let emailData: any[] = [];
    if (emailResult && emailResult.data && emailResult.data.messages) {
      emailData = emailResult.data.messages;
      summary += `Found ${emailData.length} recent emails:\n\n`;

      for (let i = 0; i < emailData.length; i++) {
        const message = emailData[i];
        const subject = message.subject || "No subject";
        const from = message.from || "Unknown sender";
        summary += `${i + 1}. **${subject}**\n   From: ${from}\n\n`;
      }
    } else {
      summary += "No emails found or unable to fetch emails.\n";
    }

    console.log("Summary created:", summary);

    // Step 3: Post the summary to Slack channel
