import { Composio } from "@composio/core";
import { OpenAIProvider } from "@composio/openai";
import { OpenAI } from "openai";
import * as fs from "fs";

async function main() {
  // Read trial_id from /logs/trial_id
  const trialIdPath = "/logs/trial_id";
  const trialId = fs.readFileSync(trialIdPath, "utf-8").trim();
  console.log(`Trial ID: ${trialId}`);

  // Initialize Composio with OpenAIProvider
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY || "",
    provider: new OpenAIProvider(),
  });

  // Initialize OpenAI
  const openai = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY || "",
    timeout: 60000, // 60 second timeout
    maxRetries: 2,
  });

  const userId = "zealt-user01";
  console.log(`User ID: ${userId}`);

  try {
    // Create a session for the user
    console.log("Creating session...");
    const session = await composio.create(userId, {
      toolkits: ["gmail", "slack"],
    });

    // Get the meta tools from the session
    const tools = await session.tools();
    console.log(`Got ${tools.length} meta tools`);
    console.log("Meta tools:", tools.map((t: any) => t.function?.name || t.name).join(", "));

    // Step 1: Fetch the last 5 emails from Gmail using the agent
    console.log("Fetching last 5 emails from Gmail...");

