      let summary = "📧 **Email Summary**\n\n";

      if (emailData && emailData.length > 0) {
        summary += `Found ${emailData.length} recent emails:\n\n`;

        for (let i = 0; i < Math.min(emailData.length, 5); i++) {
          const message = emailData[i];
          const subject = message.subject || "No subject";
          const from = message.from || "Unknown sender";
          summary += `${i + 1}. **${subject}**\n   From: ${from}\n\n`;
        }
